ALTER TABLE public.community_news ADD COLUMN ad_image_bucket text NOT NULL DEFAULT 'shop-ads';
CREATE FUNCTION public.set_news_watermarked_media(_id uuid,_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (has_role(auth.uid(),'admin') OR is_super_admin()) THEN RAISE EXCEPTION 'Admins only'; END IF; IF split_part(_path,'/',1)<>auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='community-news' AND name=_path) THEN RAISE EXCEPTION 'Upload the watermarked media first'; END IF; UPDATE community_news SET media_path=_path,watermarked=true WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'News not found'; END IF; END $$;
REVOKE EXECUTE ON FUNCTION public.set_news_watermarked_media(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_news_watermarked_media(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.set_news_sponsor_image(_id uuid,_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (has_role(auth.uid(),'admin') OR is_super_admin()) THEN RAISE EXCEPTION 'Admins only'; END IF; IF split_part(_path,'/',1)<>auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='community-news' AND name=_path) THEN RAISE EXCEPTION 'Upload the sponsor photo first'; END IF; UPDATE community_news SET ad_image_path=_path,ad_image_bucket='community-news' WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'News not found'; END IF; END $$;
REVOKE EXECUTE ON FUNCTION public.set_news_sponsor_image(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_news_sponsor_image(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.preserve_news_sponsor_image() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.ad_link LIKE '/ad/%' THEN NEW.ad_image_bucket:='shop-ads'; ELSIF OLD.ad_image_bucket='community-news' AND NEW.ad_title IS NOT NULL THEN NEW.ad_image_path:=OLD.ad_image_path; NEW.ad_image_bucket:='community-news'; END IF; RETURN NEW; END $$;
CREATE TRIGGER preserve_news_sponsor_image BEFORE UPDATE ON public.community_news FOR EACH ROW EXECUTE FUNCTION public.preserve_news_sponsor_image();